with metrics as (select id, customer_id, device, browser, started_at, first_value(browser) ignore nulls over w_grp as first_known_browser, last_value(country, true) over (order by started_at, id rows between unbounded preceding and current row) as last_known_country, row_number() over (partition by device, browser order by started_at, id) as row_seq, row_number() over w_grp_2 as seq_no from sessions window w_grp as (partition by device order by started_at, id rows between unbounded preceding and current row), w_grp_2 as (partition by device order by started_at desc, id)) select id, device, browser, first_known_browser, seq_no from metrics;
